const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stopwords=new Set(('a an and are as at be been being but by can could did do does for from had has have he her here him his how i if in into is it its just me more most my no not of on one or our out she so some than that the their them then there these they this those to too up us very was we were what when where which who why will with would you your museum museums really also get got like much many went visit visited visiting good great see seen place places thing things something time people think know want make made even well still day go going said way 看了 这个 那个 一个 一些 这里 那里 还有 就是 但是 因为 所以 可以 觉得 真的 非常 比较 我们 你们 他们 自己 什么 怎么 已经 没有 不是 以及 一次 参观 博物馆').split(/\s+/));
const culturalTerms=['青铜器','传统工艺','亲子研学','历史文化','铸造','手作','预约','排队','国风','讲解'];
function tokens(text,segmenter){return text.split(new RegExp('('+culturalTerms.join('|')+')','g')).flatMap(part=>culturalTerms.includes(part)?[part]:segmenter?[...segmenter.segment(part)].filter(s=>s.isWordLike).map(s=>s.segment):part.match(/[a-z]{2,}|[\p{Script=Han}]{2,6}/gu)||[]);}
export function countWords(posts){
 const rows=posts.filter(p=>p.kind!=='manual'&&typeof p.text==='string'),counts=new Map(),segmenter=typeof Intl.Segmenter==='function'?new Intl.Segmenter('zh-CN',{granularity:'word'}):null;
 for(const post of rows){const text=post.text.normalize('NFKC').replace(/https?:\/\/\S+|[\w.+-]+@[\w.-]+\.[a-z]{2,}|<[^>]*>/gi,' ').toLowerCase(),seen=new Set(),segments=tokens(text,segmenter);
  for(const word of segments){if(word.length<2||word.length>32||stopwords.has(word)||!/[\p{L}]/u.test(word)||/\d/.test(word))continue;const item=counts.get(word)||{word,count:0,documents:0};item.count++;if(!seen.has(word)){item.documents++;seen.add(word);}counts.set(word,item);}
 }
 return {total:rows.length,historical:rows.filter(p=>p.kind==='visitor-review').length,words:[...counts.values()].sort((a,b)=>b.count-a.count||b.documents-a.documents||a.word.localeCompare(b.word)).slice(0,100)};
}
export function cloudSVG(words,{catalog=false,selected=""}={}){
 const boxes=[],placed=[],colors=['#008b80','#176e9a','#274868','#4b7f76','#637aa5'];if(catalog)colors.push('#8a4e71','#925918','#535a9c');const max=words[0]?.count||1,min=words.at(-1)?.count||1;
 for(const [index,item]of words.slice(0,65).entries()){const size=Math.round((catalog?18:15)+(catalog?40:29)*(Math.log(item.count)-Math.log(min))/Math.max(1,Math.log(max)-Math.log(min))),width=[...item.word].reduce((n,c)=>n+(/[\p{Script=Han}]/u.test(c)?1:.64),0)*size+14,height=size*1.22+8;let box;
  for(let step=0;step<(catalog?4200:1800);step++){const angle=step*.38,radius=2.25*Math.sqrt(step),x=450+Math.cos(angle)*radius*5-width/2,y=(catalog?185:165)+Math.sin(angle)*radius*(catalog?2.1:1.7)-height/2,candidate={x,y,w:width,h:height};if(x<12||y<8||x+width>888||y+height>(catalog?362:322))continue;if(!boxes.some(b=>x<b.x+b.w&&x+width>b.x&&y<b.y+b.h&&y+height>b.y)){box=candidate;break;}}
  if(!box)continue;boxes.push(box);
  const label=catalog?`${item.word}，涉及 ${item.count} 件展品`:`${item.word}：出现 ${item.count} 次，涉及 ${item.documents} 条评论`;
  const link=catalog?`href="#dna" data-catalog="word" data-id="${escape(item.word)}"`:`href="#analysis" data-cloud-word="${escape(item.word)}"`;
  placed.push(`<a ${link} aria-label="${escape(label)}"><title>${escape(label)}</title><text x="${(box.x+box.w/2).toFixed(1)}" y="${(box.y+box.h*.73).toFixed(1)}" text-anchor="middle" font-size="${size}" font-weight="${item.word===selected||item.count>min?700:index<12?650:450}" fill="${colors[index%colors.length]}" ${item.word===selected?'text-decoration="underline"':''}>${escape(item.word)}</text></a>`);
 }
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 ${catalog?370:330}" role="${catalog?'group':'img'}" aria-label="${catalog?'展品关键词词云':'全部已载入评论的词频云图'}" style="width:100%;height:auto;font-family:Arial,'Microsoft YaHei',sans-serif"><rect width="900" height="${catalog?370:330}" fill="#f5faf9" rx="14"/>${placed.join('')}</svg>`;
}
export function wordCloudPanel(posts){const data=countWords(posts);return `<section class="panel wordcloud-panel"><div class="panel-title"><h3>全部已载入评论 · 词云</h3><span class="tag">本地词频统计 · 不调用 AI</span></div><p>共 ${data.total} 条评论，含 ${data.historical} 条历史参观反馈；不受表格筛选或分页影响，手动测试文本不纳入。新增获取或导入后自动更新。</p>${data.words.length?cloudSVG(data.words):'<p class="muted">暂无可展示词语。获取或导入评论后自动生成。</p>'}<p class="muted">字号表示词语出现次数。使用中英文分词、文化词典与停用词表，未做语义合并；高频词不代表正面态度、参观意愿或用户画像。混合历史与近期来源，只反映当前数据集。</p><div class="toolbar"><button data-act="export-cloud" ${data.words.length?'':'disabled'}>导出词频 CSV</button><button data-act="export-cloud-svg" ${data.words.length?'':'disabled'}>下载词云 SVG</button></div><details><summary>查看词频与涉及评论数（前 ${data.words.length} 个词）</summary><div class="table-wrap"><table><thead><tr><th>词语（点击查看证据）</th><th>出现次数</th><th>涉及评论数</th></tr></thead><tbody>${data.words.map(w=>`<tr><td><button data-cloud-word="${escape(w.word)}">${escape(w.word)}</button></td><td>${w.count}</td><td>${w.documents}</td></tr>`).join('')}</tbody></table></div></details></section>`;}
